using UnityEngine;

namespace TurnBasedRpg.Game
{
    /// <summary>
    /// Every asset the game uses at run time, generated by ProjectBuilder (editor) so the scene only
    /// needs one reference. Models are assembled from these meshes in code.
    /// </summary>
    [CreateAssetMenu(fileName = "GameArt", menuName = "Turn-Based RPG/Game Art")]
    public sealed class GameArt : ScriptableObject
    {
        [Header("Materials")]
        public Material Lit;
        public Material Ring;
        public Material ParticleAdditive;
        public Material ParticleAlpha;

        [Header("Meshes")]
        public Mesh Cube;
        public Mesh Sphere;
        public Mesh Cylinder;
        public Mesh Capsule;
        public Mesh Quad;

        [Header("Music")]
        public AudioClip RoadTheme;
        public AudioClip BattleTheme;
        public AudioClip BossTheme;

        [Header("Sound effects")]
        public AudioClip Move;
        public AudioClip Confirm;
        public AudioClip Cancel;
        public AudioClip Slash;
        public AudioClip Critical;
        public AudioClip Fire;
        public AudioClip Heal;
        public AudioClip Buff;
        public AudioClip Curse;
        public AudioClip Stun;
        public AudioClip Guard;
        public AudioClip Item;
        public AudioClip UnitDown;
        public AudioClip YourTurn;
        public AudioClip LevelUp;
        public AudioClip Victory;
        public AudioClip Defeat;
        public AudioClip Roar;
    }
}
